// ---- Tests go in the same file or a separate tests module ----

// ---- A simple function to test ----
fn add(a: i32, b: i32) -> i32 {
    a + b
}

fn divide(a: f64, b: f64) -> Option<f64> {
    if b == 0.0 {
        None
    } else {
        Some(a / b)
    }
}

fn parse_number(s: &str) -> Result<i32, String> {
    s.parse().map_err(|_| format!("Invalid number: {}", s))
}

fn factorial(n: u32) -> u32 {
    (1..=n).product()
}

// ---- Test module ----
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_add() {
        assert_eq!(add(2, 3), 5);
        assert_eq!(add(-1, 1), 0);
        assert_eq!(add(0, 0), 0);
    }

    #[test]
    fn test_divide() {
        assert_eq!(divide(10.0, 2.0), Some(5.0));
        assert_eq!(divide(10.0, 0.0), None);
    }

    #[test]
    fn test_parse_number() {
        assert_eq!(parse_number("42"), Ok(42));
        assert!(parse_number("abc").is_err());
    }

    #[test]
    fn test_factorial() {
        assert_eq!(factorial(0), 1);
        assert_eq!(factorial(1), 1);
        assert_eq!(factorial(5), 120);
    }

    #[test]
    #[should_panic(expected = "attempt to multiply with overflow")]
    fn test_factorial_overflow() {
        // This would overflow for large numbers
        let _ = factorial(100);  // Actually u32 will overflow for > 12!
    }

    #[test]
    fn test_divide_by_zero_handling() {
        let result = divide(10.0, 0.0);
        assert_eq!(result, None);
        assert!(result.is_none());
    }

    #[test]
    fn test_multiple_assertions() {
        let result = parse_number("42");
        assert!(result.is_ok());
        let value = result.unwrap();
        assert_eq!(value, 42);
        assert!(value > 0);
        assert!(value < 100);
    }

    #[test]
    fn test_parse_number_with_error() {
        let result = parse_number("abc");
        match result {
            Err(e) => assert!(e.contains("abc")),
            _ => panic!("Should have failed"),
        }
    }
}

// ---- Integration tests ----
// These go in the tests/ directory

// ---- Running tests ----
// cargo test
// cargo test -- --nocapture (to see output)
// cargo test test_add (run specific test)

